INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3339, 'ruRU', 'Предмет 1 из 1.', 12340),
(3345, 'ruRU', 'Предмет 1 из 5.', 12340),
(3398, 'ruRU', 'Чувствуешь себя немного подавленным? Нужна энергия? А как насчёт море энергии? Как насчёт горячей, огненной взрывной энергии?\n\nПопробуй новый ЛАВОВЫЙ ВЗРЫВ от Пироко. Ты влюбишься в его сладкий, освежающий вкус и необработанную силу внутри. Нужен быстрый заряд бодрости? Нет проблем! ЛАВОВЫЙ ВЗРЫВ восстановит тебя, даже когда ты истощён до предела.', 14007),
(3399, 'ruRU', 'Серьёзно ранен? Мы тебя прикроем! ЛАВОВЫЙ ВЗРЫВ даст тебе ту дополнительную энергию, которая нужна, чтобы найти путь к безопасности!*\nЛюбишь огонь? Задумывался когда-нибудь, как круто было бы пить жидкий огонь? Если да, тебе понравится новый ЛАВОВЫЙ ВЗРЫВ от Пироко! Познай вкус ожога!\n\n*Недавние исследования показали, что Лавовый Взрыв на самом деле может никак не помогать в заживлении ран. Есть вероятность, что Лавовый Взрыв может на самом деле вызвать обильное кровотечение из, казалось бы, случайных отверстий.', 14007),
(3400, 'ruRU', 'Предупреждение: Лавовый Взрыв не для всех. Беременным женщинам, детям и женщинам, которые могут быть беременны или кормят грудью, следует проконсультироваться с врачом перед употреблением Лавового Взрыва.\n', 14007),
(3401, 'ruRU', 'Возможные побочные эффекты могут включать: сухость во рту, расстройство желудка, сухость глаз, несварение, боль в спине, боль в костях и суставах, лёгкое обезображивание, внутреннее кровотечение, временное безумие, зависимость от Лавового Взрыва, зависимость от магии, пироманию, боязнь паука, светящиеся глаза, учащённое сердцебиение, лихорадку, внезапные роды, недосыпание, уязвимость к холодному железу, истерию, случайные песни, всплывающие в голове, астму, демоническую одержимость, головные боли, боли в ногах, неспособность произносить букву «р» и смерть.\n', 14007),
(3402, 'ruRU', 'Осторожно: употребление нескольких Лавовых Взрывов подряд может привести к самовозгоранию.\n\nПопробуй новый ЛАВОВЫЙ ВЗРЫВ прямо сейчас!', 14007),
(3403, 'ruRU', 'Антонидас был всего лишь мальчиком, когда стал учеником одного из Киринтора. Он был упорным учеником, часами просиживая над книгами в магических библиотеках Даларана. Спустя всего несколько лет учёбы в секте Антонидас превзошёл своих сверстников и заслужил их восхищение, а также уважение старших.', 17538),
(3404, 'ruRU', 'В возрасте 12 лет диссертация Антонидаса «Последствия превращения феномена обратного путешествия во времени в измеримую магическую практику» принесла ему Пояс Высшей Проницательности Киринтора, сделав его самым юным обладателем этой награды. Вскоре после этого Правящий совет предложил ему официальное место в Секте Передовых Исследований и Просвещения Киринтора, также сделав его самым юным получателем официального приглашения.', 17538),
(3405, 'ruRU', 'С возрастом маг продолжал учиться и совершенствовать свои способности. Его природный талант к защитной магии и мудрость не по годам сделали Антонидаса идеальным кандидатом на место в Совете Шестерых, которое он в итоге занял. Антонидас показал себя не только мудрым и справедливым, но и бесконечно целеустремлённым в стремлении стать более сведущим. Он быстро стал одним из главных голосов Даларана.', 17538),
(3406, 'ruRU', 'Перед Второй войной лидеры всех азеротских народов собрались в Лордероне, чтобы обсудить угрозу вторжения орков. Архимаг Антонидас присутствовал на саммите от имени Совета Шестерых, присягнув на верность Альянсу от лица Даларана. Он также следил за успехами молодого, но чрезвычайно талантливого мага Кадгара, который служил учеником Медива во время первой войны. После Второй войны Антонидас повысил Кадгара до звания архимага и поставил его руководить миссией по входу в Тёмный портал и исследованию Дренора.', 17538),
(3407, 'ruRU', 'После Второй войны Антонидас изучал вялость орков. Архимаг опубликовал несколько трудов по своим исследованиям:\n«Причинность войны: всестороннее исследование орочьей апатии».\n«Сравнение орочьих традиций, социологии и психологических практик до и после Второй войны».\n«Эмпирическое исследование формирования и истории значимой магии Скверны и её связи с орочьей расой».', 17538),
(3408, 'ruRU', 'Выводы многих из этих отчётов в основном неубедительны. Сам Антонидас неоднократно говорил, что найти средство от недуга орков было бы практически недостижимой задачей. Его официальный вывод заключался в том, что единственный путь орков к здоровому образу жизни лежит через духовность.', 17538),
(3544, 'ruRU', 'Ты нашёл обломки загадочного объекта. За пламенем можно разобрать знак «M:1815212085». Интересно, из какого мира этот объект...', 0),
(3560, 'ruRU', 'Missing WDB data.', 0),
(3567, 'ruRU', '<br /><br /><h1 align="center">Светлая память</h1><br /><h1 align="center">Шалдин, Гершала, Волкор</h1><h1 align="center">и тем, кто не вернулся домой.</h1>', 1),
(3577, 'ruRU', 'Добро пожаловать в Секретную Лабораторию, самое увлекательное новое место для туристов Азшары!<br /><br /><br />Вы когда-нибудь задумывались, откуда берутся секреты?<br /><br /><br />Глубоко в богатых ресурсами лесах живописной Азшары гоблинские учёные усердно трудятся, изобретая секреты завтрашнего дня, чтобы вы могли наслаждаться ими уже сегодня! За небольшую предоплату вы и вся ваша семья можете получить место в первом ряду и наблюдать, как опытные гоблинские инженеры прощупывают и дразнят саму ткань космоса.', 1),
(3578, 'ruRU', 'Зачем мы здесь? Что делает нас разумными? Сколько кило-фрапов летучей энергии мы можем сжать в кубическую унцию опасно взрывоопасного ракетного топлива, прежде чем оно достигнет критической массы и высвободит ударную волну, способную сбить планету с оси? Мы можем узнать это вместе. Ваша секретная лаборатория ждёт!<br /><br /><br /><Оставшиеся 36 страниц брошюры состоят из сложных юридических отказов от ответственности и бланка заказа в магазине подарков.>', 1),
(3579, 'ruRU', 'Тем из нас, кто проворен умом, но не слишком проворен телом, приходится искать... альтернативные способы самосохранения. Многие такие люди выбирают карьеру в магических делах.$B$B$N, я наблюдал за тобой, и твой разум — как стальной капкан. Однако, чтобы процветать в это время перемен, такому, как ты, понадобится овладеть тайными искусствами. А чтобы овладеть тайными искусствами, тебе придётся поговорить со мной.$B$BПриходи поговорить со мной в Над-Кузню. Нам есть что обсудить.$B$B-Тигли Мерровит', 1),
(3580, 'ruRU', 'Знай: шаман никогда не должен требовать силы; поступить так — разгневать стихии, а шаман без защиты стихий ничто. Те, кто следует путём шамана, никогда не должны забывать этот важнейший завет.$B$BОднако шаман, работающий в уважительном союзе со стихиями, обретает силу, которой мало кто может сравниться. Если ты чувствуешь в себе смирение для этого, приходи навестить меня в Над-Кузне. Я научу тебя — так же, как учили меня — работать со стихиями огня, земли, ветра, воды и дикой природы.$B$B~Тео Громошторм', 1),
(3581, 'ruRU', '"Ролевая игра"\n\nХорошие навыки ролевой игры жизненно необходимы. Ни одна гениальная гномиха не хочет гигантского занудства. Очаруй её рассказами о твоих будущих межконтинентальных приключениях:\n\n  "Ты и я, детка, мы полетим в Калимдор, вырежем наши имена на боку Тельдрассила и проведём остаток жизни, качаясь на ветках в кратере Ун''горо."\n\n"Рассказывание историй"\n\nПоделись историями о вашем захватывающем совместном будущем! Чем неправдоподобнее, тем лучше. Ничто не возбуждает гномиху так, как амбициозный план. Это также отличный повод для разговора!\n\n  "Объединив наши блестящие умы, мы могли бы вернуть Гномреган. ... а почему мы вообще до сих пор не вернули Гномреган?"', 19831),
(3582, 'ruRU', '"Поддразнивание"\n\nПоддразнивание — искусство шутливо высмеивать женщину. Будь осторожен, легко можно перейти границу. Назвав её "Гоблинской Гэнк-мошкой", ты пойдёшь домой, нося тот Зелёный Гордокский Эль, который ты только что купил. Попробуй что-нибудь более тонкое. \n\nЕсли она ведёт себя по-детски и не прекращает прыгать по столам в середине бара, попробуй:\n\n"Слышал, в приюте Штормграда открылась вакансия звёздного артиста."\n\nЕсли она не перестаёт болтать о себе, игриво попробуй:\n\n"А где у тебя кнопка выключения?"\n\nВАЖНОЕ ЗАМЕЧАНИЕ: у гномих НЕТ кнопки выключения. Попытка её найти может привести к потере жизни, конечностей или кошелька.', 19831),
(3583, 'ruRU', 'Твои вкусы более экзотичны? \nЖелаешь кого-то немного неземного? \nКопытца — это твоё, а суккубы чуть перебор?\n\nЧитай дальше, мой друг...', 19831),
(3584, 'ruRU', 'Я только сошёл с корабля на Лазурном берегу, когда остановил группу дамочек-дренеек в самом соку — около 230 лет. Они смеялись и прекрасно проводили время. Какая удача, ещё на причале, и я уже нашёл именно тот тип весёлых, энергичных дренейских женщин, с которыми хотел познакомиться в этой поездке. \n\nСначала немного тревожно, я глубоко вдохнул и напомнил себе: «Они тоже здесь, в Азероте, в отпуске, хотят познакомиться с новыми людьми и прекрасно провести время».\n\nИ действительно, они были в восторге увидеть одного дьявольски очаровательного гнома, такого как я, в Экзодаре. Оказалось даже, что мы оба остановились рядом с Хранилищем Света. Мы обменялись глубокими, проникновенными взглядами в глаза друг друга, пообещав встретиться снова у А''дала позже этим вечером.', 19831),
(3585, 'ruRU', 'На следующий день я встретил другую красивую дренейку — блеск её рогов давал лишь намёк на её утончённый вкус. Я спросил, почему она в гостях в Экзодаре, и, к моему удивлению, она сказала, что она здесь не в гостях — она здесь живёт. \n\nСлова, которые я говорил себе раньше, вернулись в мою голову: \n\n«Она в отпуске, хочет познакомиться с удивительными людьми и прекрасно провести время».\n\nЯ всё понял неправильно, она вообще не была в отпуске! И тогда вдруг заскрипели шестерёнки моего разума: я убеждал себя, что они такие отзывчивые, потому что в отпуске. Что за гнолльская отговорка! \n\nЯ весёлый, интересный парень, с которым любая разумная девушка захочет пойти в группу, в отпуске или нет! Теперь, встречая дренеек, я напоминаю себе простую истину:\n\n«Она тоже хочет познакомиться с людьми и прекрасно провести время».', 19831),
(3586, 'ruRU', 'Следующие 497 страниц этого словаря состоят целиком из странно ракурсных фотографий, сделанных на Супер Снэппер FX 2000.', 19831),
(3587, 'ruRU', 'Как назначить свидание дворфийке:\n\n1. Попроси её купить тебе выпить.', 19831),
(3588, 'ruRU', 'Будем честны. С конца Третьей войны девушки ночных эльфов услышали всё. На самом деле, они слышали всё это уже задолго до того, как родились мы с тобой. \n\nЕсли хочешь занять разум девушки-ночного эльфа, тебе придётся выделиться. Конечно, мы все слышали истории о девушках ночных эльфов, танцующих на почтовых ящиках и раздевающихся, чтобы заплатить за дрессировку ночной пантеры. Правда это или нет, но если хочешь заставить улыбку заиграть на губах этой прекрасной леди, тебе нужно быть уникальным, запоминающимся и уверенным в себе. \n\nНачни с того, что покажи, что ищешь больше, чем просто красотку. Конечно, она может прыгать, может танцевать, но может ли она поддержать достойный разговор? Понимает ли она вообще правильное использование самофланжа? Умеет ли она веселиться?\n\nНет ничего хуже, чем привести ночную эльфийку на вечеринку, лишь чтобы наблюдать, как она неловко стоит одна, прерывая разговор только для того, чтобы посетовать на утрату своей высокородной сестры во время Войны Древних.', 19831),
(3589, 'ruRU', 'Нет ничего сравнимого с завоеванием сердца человеческой девушки. Бесконечно прощающие, безгранично заботливые и невероятно весёлые, человеческие девушки стали причиной падения бесчисленных героев на протяжении веков. (См. Главу 3: «Джайна Праудмур и мужчины, которые её любили»)\n\nОднако поколение за поколением доказывало, что для привлечения девушки своей мечты нужно нечто большее, чем деньги, внешность или эпический доспех. Даже сила гномьего изобретательства здесь не поможет. \n\nЧтобы по-настоящему очаровать сердце другого человека, тебе следует обладать этими качествами.\n\n* Быть весёлым и дружелюбным\n* Быть вызовом\n* Быть мужчиной\n\n', 19831),
(3590, 'ruRU', 'Быть весёлым и дружелюбным\n\nБывал ли у тебя друг, который приходит к тебе домой и портит всем настроение? Ага. У всех был такой. Приглашают ли его снова на вечеринки? Только если он приносит эль. Если хочешь быть привлекательным человеком, живи привлекательной жизнью. \n\nТы обнаружишь, что чем больше тебе нравится общаться с другими, тем больше им нравится общаться с тобой! \n\nНет более быстрого способа испортить девушке вечер, чем нагнать на неё нужду и извинения. Отпусти это, прими веселье, и твоя уверенность взлетит.', 19831),
(3591, 'ruRU', 'Быть вызовом\n\nСлишком многие гномы в наши дни ходят, опустив голову, печально шаркая от таверны к таверне, безнадёжно держась за эти ограничивающие убеждения, что ни одна человеческая девушка никогда не захочет их. Они врываются в таверну, осыпают её комплиментами и бесплатными напитками, а потом идут домой удручённые. \n\nЧто ж, позволь мне первым сказать тебе, друг: когда ты отдаёшь себя так дешёво, ты умаляешь ценность своей уникальной, изысканной личности. Общество внушило тебе, что ты не приз, что женщины никогда тебя не заметят, что ты должен умолять о любви и внимании.\n\nОни ошибаются. Не раздавай свою привязанность так свободно. Вместо вопроса «Нравлюсь ли я ей?» спроси себя: «Нравится ли она мне?» \n\nБрось ей вызов — покажи, что ищешь девушку, предлагающую больше, чем красивое лицо. Если она не может угнаться за твоей жизнью, иди дальше. Если она показывает, что у неё есть что предложить, ты в начале чего-то прекрасного.', 19831),
(3592, 'ruRU', 'Быть мужчиной\n\nВ эпоху, когда нас изгнали из наших домов, заставили сражаться за само наше выживание и столкнули лицом к лицу с ужасами, невиданными прежде в Азероте, можно подумать, что природа мужественности была бы лучше понята. \n\nК сожалению, искусство мужественности было утрачено, смыто блеском и гламуром битвы. Однако не всё потеряно! С практикой и уверенностью ты можешь вновь обрести связь с собой. \n\nКогда ты встретил человеческую девушку своей мечты, и она показала себя достойной твоей привязанности:\n\n* Бери на себя инициативу — покажи ей всё прекрасное в твоём мире\n* Держи её за руку — развивай близкие, тёплые отношения\n* Проявляй уважение — к себе, к ней и к миру вокруг\n\nПревыше всего:\n\n* Будь ответственным\n', 19831),
(3593, 'ruRU', 'Устранение неполадок\n\nХотя не всё всегда идёт так, как ты ожидаешь, именно это делает жизнь непредсказуемой и увлекательной. Однако есть несколько советов, которые помогут тебе значительно улучшить свою жизнь. Вот некоторые распространённые ошибки:\n\n* Не гонись\n* Не будь навязчивым\n* Не зацикливайся на той, кому ты не нравишься\n\nВсё это исходит из коренного убеждения, что тебе непременно нужна именно та женщина, с которой ты сейчас разговариваешь. Освободись — в этом прекрасном мире много женщин, и если с одной не получилось, отпусти. Ты обнаружишь, что становишься привлекательнее, чем меньше ты цепляешься.\n', 19831),
(3596, 'ruRU', 'Поистине редки «призматические» клинки, выкованные объединённой волей пяти драконьих родов. Среди величайших из этих клинков были клинки-сёстры Квель''Серрар и Квель''Делар.\nВ своей мудрости драконья королева Алекстраза подарила по одному клинку каждому из эльфийских народов Азерота. Квель''Серрар предстояло нести доблестному калдорайскому воину, в то время как Квель''Делар был доверен чемпиону квель''дорей.\nКаждый клинок преображался в руках своего владельца, формируя свою магию в соответствии с силами своего хозяина...', -388),
(3597, 'ruRU', 'Тебе нужно встретиться с чародейкой Тибалин на верхнем этаже Серебряного анклава. Она доверит тебе книгу, которая не имеет цены. Будь осторожен в своих перемещениях и охраняй эту книгу своей жизнью. Отнеси её обратно Каладис Ясное Копьё к покою Квель''Делара со всей поспешностью.', -388),
(3598, 'ruRU', 'Тебе нужно встретиться с магистром Хаторелом внутри «Грязного зверя». Он доверит тебе книгу, которая не имеет цены. Будь осторожен в своих перемещениях и охраняй эту книгу своей жизнью. Доставь её Миралиону Солнечному Клинку к покою Квель''Делара со всей поспешностью.', -388),
(3604, 'ruRU', 'Как Отрекшиеся, мы сражаемся против Короля-лича, мы сражаемся против Альянса... иногда мы даже ссоримся с другими расами Орды. Нас мало, и мы сталкиваемся с огромными препятствиями... но мы выживем и победим.$b$bКак и товарищ-охотник, ты будешь делать это издалека, с луком в руке и животным-спутником рядом. Твоя сила исходит не из тайного волшебства или воинского мастерства, а из твоей способности жить с земли.$b$bПуть охотника лежит перед тобой. Он начинается с меня, твоего наставника. Где он заканчивается... мы пока не знаем.', 14333),
(3610, 'ruRU', 'Остальные не понимают нас. Они делают вид, что ладят с нами, но это не так. Даже колдуны боятся нас.$B$BНо ничего, ведь у нас есть друг друга. Орки-маги, объединяйтесь! Я и ты! Акрифа и... как бы тебя там ни звали! Ха!$B$BМы покажем им, из чего мы сделаны. Загляни ко мне, и я поделюсь с тобой некоторыми тайнами тайной магии, которые мне удалось освоить.', 1),
(3611, 'ruRU', 'Когда пламя поглотит Азерот, где будешь ты?\n\nМы знаем, что никто не хочет размышлять о своей неминуемой гибели, но стоит подумать о том, где ты проведёшь загробную жизнь.\n\nНаши мудрецы предсказали, что конец мира близок, и выживут только подготовленные. Мы можем помочь тебе выжить в бушующем пекле, которое очистит этот мир от нечестивых. Не пора ли обрести душевный покой?', 0),
(3612, 'ruRU', 'Ты, без сомнения, слышал фразу «всё хорошее когда-нибудь кончается», и так же обстоит дело с твоей жизнью в Азероте. Пройдёт не так много времени, прежде чем мир погрузится в хаос, когда стихии вернут себе своё по праву рождения.\n\nНо тебе не нужно бояться в эти тревожные времена. Тебе не нужно умирать. Мы можем помочь тебе вознестись к новому образу жизни, за пределами смерти, страха и бессилия смертности. Присоединяйся к нам сегодня.', 0);
